def send_message(self, prompt_path=None, prompt_data=None, function_calls: FunctionCallSet=None):
    '\n        Sends a message in the conversation.\n\n        Args:\n            prompt_path: The path to a prompt.\n            prompt_data: Data associated with the prompt.\n            function_calls: Optional function calls to be included in the message.\n\n        Returns:\n            The response from the agent.\n        '
    self.construct_and_add_message_from_prompt(prompt_path, prompt_data)
    if (self.agent.__class__.__name__ == 'Developer'):
        self.agent.project.llm_req_num += 1
    development_step = get_saved_development_step(self.agent.project)
    if ((development_step is not None) and self.agent.project.skip_steps):
        print(yellow(f'Restoring development step with id {development_step.id}'))
        self.agent.project.checkpoints['last_development_step'] = development_step
        self.agent.project.restore_files(development_step.id)
        response = development_step.llm_response
        self.messages = development_step.messages
        if (self.agent.project.skip_until_dev_step and (str(development_step.id) == self.agent.project.skip_until_dev_step)):
            self.agent.project.skip_steps = False
            delete_all_subsequent_steps(self.agent.project)
            if (('delete_unrelated_steps' in self.agent.project.args) and self.agent.project.args['delete_unrelated_steps']):
                self.agent.project.delete_all_steps_except_current_branch()
        if development_step.token_limit_exception_raised:
            raise TokenLimitError(development_step.token_limit_exception_raised)
    else:
        try:
            response = create_gpt_chat_completion(self.messages, self.high_level_step, self.agent.project, function_calls=function_calls)
        except TokenLimitError as e:
            save_development_step(self.agent.project, prompt_path, prompt_data, self.messages, '', str(e))
            raise e
        if (self.agent.__class__.__name__ == 'Developer'):
            development_step = save_development_step(self.agent.project, prompt_path, prompt_data, self.messages, response)
    if (response == {}):
        logger.error('Aborting with "OpenAI API error happened"')
        raise Exception('OpenAI API error happened.')
    response = parse_agent_response(response, function_calls)
    message_content = (response[0] if (type(response) == tuple) else response)
    if isinstance(message_content, list):
        if ('to_message' in function_calls):
            string_response = function_calls['to_message'](message_content)
        elif ((len(message_content) > 0) and isinstance(message_content[0], dict)):
            string_response = [(f'''#{i}
''' + array_of_objects_to_string(d)) for (i, d) in enumerate(message_content)]
        else:
            string_response = [('- ' + r) for r in message_content]
        message_content = '\n'.join(string_response)
    logger.info('\n>>>>>>>>>> Assistant Prompt >>>>>>>>>>\n%s\n>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>', message_content)
    self.messages.append({'role': 'assistant', 'content': message_content})
    self.log_message(message_content)
    return response

def execute_command(project, command, timeout=None, success_message=None, process_name: str=None, force=False) -> (str, str, int):
    "\n    Execute a command and capture its output.\n\n    Args:\n        project: The project associated with the command.\n        command (str): The command to run.\n        timeout (int, optional): The maximum execution time in milliseconds. Default is None.\n        success_message: A message to look for in the output of the command to determine if successful or not.\n        process_name (str, optional): A name for the process.\n                            If `timeout` is not provided, can be used to terminate the process.\n        force (bool, optional): Whether to execute the command without confirmation. Default is False.\n\n    Returns:\n        cli_response (str): The command output\n                            or: '', 'DONE' if user answered 'no' or 'skip'\n        llm_response (str): 'DONE' if 'no', 'skip' or `success_message` matched.\n                            Otherwise `None` - caller should send `cli_response` to LLM\n        exit_code (int): The exit code of the process.\n    "
    if (timeout is not None):
        if (timeout < 0):
            timeout = None
        else:
            if (timeout < 1000):
                timeout *= 1000
            timeout = min(max(timeout, MIN_COMMAND_RUN_TIME), MAX_COMMAND_RUN_TIME)
    if (not force):
        print(yellow_bold('\n--------- EXECUTE COMMAND ----------'))
        question = f'Can I execute the command: `{yellow_bold(command)}`'
        if (timeout is not None):
            question += f' with {timeout}ms timeout?'
        else:
            question += '?'
        answer = ask_user(project, question, False, hint='If yes, just press ENTER')
        print(('answer: ' + answer))
        if (answer == 'no'):
            return ('', 'DONE', None)
        elif (answer == 'skip'):
            return ('', 'DONE', None)
    if (('cd ' in command) or ('source ' in command)):
        command = (("bash -c '" + command) + "'")
    project.command_runs_count += 1
    command_run = get_saved_command_run(project, command)
    if ((command_run is not None) and project.skip_steps):
        project.checkpoints['last_command_run'] = command_run
        print(yellow(f'''Restoring command run response id {command_run.id}:
```
{command_run.cli_response}```'''))
        return (command_run.cli_response, None, None)
    return_value = None
    was_success = None
    q_stderr = queue.Queue()
    q = queue.Queue()
    process = run_command(command, project.root_path, q, q_stderr)
    if (process_name is not None):
        terminate_named_process(process_name)
        running_processes[process_name] = (command, process.pid)
    output = ''
    stderr_output = ''
    start_time = time.time()
    try:
        while True:
            elapsed_time = (time.time() - start_time)
            if (process.poll() is not None):
                time.sleep(0.1)
    except :
        elapsed_time = 0

def execute_command3(self, command, timeout=None, success_message=None, process_name: str=None, force=False) -> (str, str, int):
            if ((timeout is not None) and ((elapsed_time * 1000) > timeout)):
                if (process_name is not None):
                    logger.info(f'Process "{process_name}" running after timeout as pid: {process.pid}')
                    break
                raise TimeoutError('Command exceeded the specified timeout.')
            try:
